CREATE TYPE "Role" AS ENUM ('SUPER_ADMIN','STAFF','USER','PARTICIPANT');
CREATE TYPE "Permission" AS ENUM ('CREATE_QUIZ','EDIT_QUIZ','DELETE_QUIZ','START_QUIZ','END_QUIZ','VIEW_RESULTS','VIEW_ANALYTICS');
CREATE TYPE "QuizStatus" AS ENUM ('DRAFT','PUBLISHED','LIVE','ENDED','ARCHIVED');
CREATE TYPE "Difficulty" AS ENUM ('EASY','MEDIUM','HARD');
CREATE TYPE "QuestionType" AS ENUM ('MULTIPLE_CHOICE','TRUE_FALSE');
CREATE TYPE "ResultVisibility" AS ENUM ('AFTER_COMPLETION','HIDDEN');
CREATE TABLE "User"("id" TEXT NOT NULL,"fullName" TEXT NOT NULL,"username" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"collegeId" TEXT,"department" TEXT,"year" INTEGER,"section" TEXT,"email" TEXT,"phone" TEXT,"profilePhoto" TEXT,"role" "Role" NOT NULL DEFAULT 'USER',"isActive" BOOLEAN NOT NULL DEFAULT true,"mustChangePassword" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"lastLoginAt" TIMESTAMP(3),CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_username_key" ON "User"("username");
CREATE TABLE "StaffPermission"("id" TEXT NOT NULL,"permission" "Permission" NOT NULL,CONSTRAINT "StaffPermission_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "StaffPermission_permission_key" ON "StaffPermission"("permission");
CREATE TABLE "UserPermission"("userId" TEXT NOT NULL,"permissionId" TEXT NOT NULL,CONSTRAINT "UserPermission_pkey" PRIMARY KEY ("userId","permissionId"));
CREATE TABLE "Quiz"("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT,"subject" TEXT,"department" TEXT,"year" INTEGER,"difficulty" "Difficulty" NOT NULL DEFAULT 'MEDIUM',"status" "QuizStatus" NOT NULL DEFAULT 'DRAFT',"joinCode" TEXT NOT NULL,"startTime" TIMESTAMP(3),"endTime" TIMESTAMP(3),"timeLimit" INTEGER,"resultVisibility" "ResultVisibility" NOT NULL DEFAULT 'AFTER_COMPLETION',"leaderboardEnabled" BOOLEAN NOT NULL DEFAULT true,"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Quiz_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Quiz_joinCode_key" ON "Quiz"("joinCode");
CREATE TABLE "Question"("id" TEXT NOT NULL,"quizId" TEXT NOT NULL,"questionText" TEXT NOT NULL,"questionType" "QuestionType" NOT NULL DEFAULT 'MULTIPLE_CHOICE',"points" INTEGER NOT NULL DEFAULT 10,"timeLimit" INTEGER,"explanation" TEXT,"order" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Question_pkey" PRIMARY KEY ("id")); CREATE INDEX "Question_quizId_order_idx" ON "Question"("quizId","order");
CREATE TABLE "QuestionOption"("id" TEXT NOT NULL,"questionId" TEXT NOT NULL,"optionText" TEXT NOT NULL,"isCorrect" BOOLEAN NOT NULL DEFAULT false,"order" INTEGER NOT NULL,CONSTRAINT "QuestionOption_pkey" PRIMARY KEY ("id")); CREATE INDEX "QuestionOption_questionId_order_idx" ON "QuestionOption"("questionId","order");
CREATE TABLE "QuizSession"("id" TEXT NOT NULL,"quizId" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"endedAt" TIMESTAMP(3),"currentIndex" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "QuizSession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Participant"("id" TEXT NOT NULL,"quizId" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"quizSessionId" TEXT NOT NULL,"name" TEXT NOT NULL,"collegeId" TEXT,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3),CONSTRAINT "Participant_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Participant_sessionId_key" ON "Participant"("sessionId"); CREATE INDEX "Participant_quizId_joinedAt_idx" ON "Participant"("quizId","joinedAt");
CREATE TABLE "Answer"("id" TEXT NOT NULL,"participantId" TEXT NOT NULL,"questionId" TEXT NOT NULL,"selectedOptionId" TEXT,"isCorrect" BOOLEAN NOT NULL,"pointsEarned" INTEGER NOT NULL,"responseTime" INTEGER,"submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Answer_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Answer_participantId_questionId_key" ON "Answer"("participantId","questionId");
CREATE TABLE "QuizResult"("id" TEXT NOT NULL,"participantId" TEXT NOT NULL,"quizId" TEXT NOT NULL,"score" INTEGER NOT NULL,"totalPoints" INTEGER NOT NULL,"correctAnswers" INTEGER NOT NULL,"incorrectAnswers" INTEGER NOT NULL,"accuracy" DOUBLE PRECISION NOT NULL,"timeTaken" INTEGER,"rank" INTEGER,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "QuizResult_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "QuizResult_participantId_key" ON "QuizResult"("participantId"); CREATE INDEX "QuizResult_quizId_score_idx" ON "QuizResult"("quizId","score");
CREATE TABLE "ActivityLog"("id" TEXT NOT NULL,"userId" TEXT,"action" TEXT NOT NULL,"targetType" TEXT,"targetId" TEXT,"metadata" JSONB,"ipAddress" TEXT,"userAgent" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ActivityLog_pkey" PRIMARY KEY ("id")); CREATE INDEX "ActivityLog_createdAt_idx" ON "ActivityLog"("createdAt"); CREATE INDEX "ActivityLog_userId_createdAt_idx" ON "ActivityLog"("userId","createdAt");
CREATE TABLE "QuizSetting"("id" TEXT NOT NULL,"quizId" TEXT NOT NULL,"shuffleQuestions" BOOLEAN NOT NULL DEFAULT false,"shuffleOptions" BOOLEAN NOT NULL DEFAULT false,"showCorrectAnswers" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "QuizSetting_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "QuizSetting_quizId_key" ON "QuizSetting"("quizId");
ALTER TABLE "UserPermission" ADD CONSTRAINT "UserPermission_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "UserPermission" ADD CONSTRAINT "UserPermission_permissionId_fkey" FOREIGN KEY ("permissionId") REFERENCES "StaffPermission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Quiz" ADD CONSTRAINT "Quiz_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Question" ADD CONSTRAINT "Question_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "QuestionOption" ADD CONSTRAINT "QuestionOption_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "QuizSession" ADD CONSTRAINT "QuizSession_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Participant" ADD CONSTRAINT "Participant_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Participant" ADD CONSTRAINT "Participant_quizSessionId_fkey" FOREIGN KEY ("quizSessionId") REFERENCES "QuizSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Answer" ADD CONSTRAINT "Answer_participantId_fkey" FOREIGN KEY ("participantId") REFERENCES "Participant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Answer" ADD CONSTRAINT "Answer_questionId_fkey" FOREIGN KEY ("questionId") REFERENCES "Question"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Answer" ADD CONSTRAINT "Answer_selectedOptionId_fkey" FOREIGN KEY ("selectedOptionId") REFERENCES "QuestionOption"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QuizResult" ADD CONSTRAINT "QuizResult_participantId_fkey" FOREIGN KEY ("participantId") REFERENCES "Participant"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "QuizResult" ADD CONSTRAINT "QuizResult_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ActivityLog" ADD CONSTRAINT "ActivityLog_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "QuizSetting" ADD CONSTRAINT "QuizSetting_quizId_fkey" FOREIGN KEY ("quizId") REFERENCES "Quiz"("id") ON DELETE CASCADE ON UPDATE CASCADE;
